insert into cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('sam-harvest-throughput-2026-11-12','decision','Sam: increase the harvest''s throughput','Sam, opening S644 about 23:53Z 2026-11-12, verbatim: "I want to continue progress on our commons harvesting. we are making great progress but we need to increase our throughput." Later: "Cobix is offering to work with you to design specialist bots you can commission. See comments". S644 answered with the gap census (#3189) and the wave runner (#3191).',array['program-requirements','commons','decision'],'verified','Sam, in session S644 (verbatim)','Sam Lee',now(),'SkyWren (S644)',date '2026-11-12'),
('d-lacc-22-absent-loaded-s644','decision','Los Angeles City''s 22 absent records loaded, IGETC and Cal-GETC included','The S644 conductor, 2026-11-12: step=load run 43333288596 at 23:59Z inserted Los Angeles City''s 22 records its reread left absent (18 pass), IGETC 19842 and Cal-GETC 44946 included because both are Active COCI programs there. Insert-only; the receipt on main (a0afb88c) names every key and is the rollback. Clears 22 of S643''s 25 missing display keys.',array['program-requirements','decision'],'proposed','Session call, S644 (SkyWren, the conductor); docs/reference/lanes/program-requirements-harvest.md; kb/receipts (run 43333288596)',null,null,'SkyWren (S644)',date '2026-11-12'),
('d-display-missing-threshold-s644','decision','The display apply lists a missing key and fails only above max(1%, 30)','The S644 conductor (#3190): a display statement whose key matches no program_requirement_records row is listed in the applied record and is fatal only above max(1% of statements, 30 keys); the rollback names every row sent a write. The apply pages its before-read, writes in 8 parallel calls and files its record from a confirming read. Not yet run live.',array['program-requirements','decision'],'proposed','Session call, S644 (SkyWren, the conductor); docs/reference/lanes/program-requirements-harvest.md; PR 3190',null,null,'SkyWren (S644)',date '2026-11-12'),
('d-wave-one-branch-hard-stop-s644','decision','A harvest wave: one branch, one PR, one filing job, a hard stop at $40','The S644 conductor with COBIx (#3111 comment 6839930221; #3191): a wave reads up to eight colleges on distinct hosts on one branch with one PR and one filing job. The $40 per college limit holds on the estimate and by a hard stop on actual cost as calls return; a re-run never extracts. Version 1 writes no table.',array['program-requirements','conductor','decision'],'proposed','Session call, S644 (SkyWren, the conductor); docs/reference/lanes/program-requirements-harvest.md; PR 3191',null,null,'SkyWren (S644)',date '2026-11-12'),
('d-wave-price-rate-floor-s644','decision','A wave prices a college at max(0.08, its mean filed cost) a program','The S644 conductor (#3191): the price rate is the mean cost_usd of the college''s filed records with a positive cost, errored calls included, and never below 0.08; a small sample can raise the rate and never lower it. The price is would_extract times the rate plus 25%. The conductor''s first two rate rules were wrong and reversed in review.',array['program-requirements','decision'],'proposed','Session call, S644 (SkyWren, the conductor); docs/reference/lanes/program-requirements-harvest.md; PR 3191',null,null,'SkyWren (S644)',date '2026-11-12'),
('d-passes-live-stays-equal-only-s644','decision','passes_live stays equal only; the census and headline count by the tab''s rule','The S644 conductor: passes_live, the kept-passing guard, stays equal only on purpose (S641). The tab counts arithmetic equal or unstated as passing, and the census and headline use counts_passing_on_tab (#3193). Committed records: 15,183 of 18,545 by the tab''s rule, 14,645 by passes_live. The first call, widening passes_live, was reversed the same hour.',array['program-requirements','decision'],'proposed','Session call, S644 (SkyWren, the conductor); docs/reference/lanes/program-requirements-harvest.md; PR 3193',null,null,'SkyWren (S644)',date '2026-11-12'),
('d-hours-reading-gated-sbv-coalinga-s644','decision','The no-colon hours reading reads only at San Bernardino Valley and Coalinga','The S644 conductor (#3193, three review rounds): the scorer''s noncredit ''Total Hours N-M'' reading with no colon applies only at San Bernardino Valley and Coalinga, and only with positive evidence in the record''s own section. A right record on a multi-program page may fail (accepted). The live rescore is a separate reviewed step.',array['program-requirements','decision'],'proposed','Session call, S644 (SkyWren, the conductor); docs/reference/lanes/program-requirements-harvest.md; PR 3193',null,null,'SkyWren (S644)',date '2026-11-12'),
('d-no-closed-list-separate-grade-s644','decision','Programs with no closed list get a separate grade against the college''s course list','The S644 conductor (#3192): the 1,604 active programs with no closed list in the Program Course File (no join bug; a refresh fills few) will be read and checked against the college''s own active course list as a separate grade outside the headline. Whether that grade counts in the headline is Sam''s call (Open Asks Sheet 187 card B).',array['program-requirements','decision'],'proposed','Session call, S644 (SkyWren, the conductor); docs/reference/lanes/program-requirements-harvest.md; docs/harvest_no_closed_list_diagnosis_s644.md',null,null,'SkyWren (S644)',date '2026-11-12'),
('d-cobix-offers-specialist-bots-s644','decision','COBIx''s harvest offers accepted, and two read-only bots','The S644 conductor, on Sam''s go relayed by COBIx (4:55 and 5:07 PM PT 2026-11-12): COBIx scouts sources, spot-checks five records after each wave, ranks by blast radius, and takes the SLO lane after the first paid wave. Two read-only bots, source scout and wave checker, to the contract on #3111 comment 6840743191; the sample is drawn by the filing job. Not built.',array['program-requirements','commons','conductor','decision'],'proposed','Session call, S644 (SkyWren, the conductor); docs/reference/lanes/program-requirements-harvest.md; issue 3111 comment 6840743191',null,null,'SkyWren (S644)',date '2026-11-12'),
('d-dated-reads-runner-job-s644','decision','A college PR''s dated reads refresh in a runner job','The S644 conductor (#3197): registry_read.json and map_cr_by_course.json, the display builder''s dated reads, refresh in a runner job, since roep_display_test requires the committed build to cover every filed program and a first-read college''s PR cannot go green without them. Plan the dated reads and the build as part of a first read.',array['program-requirements','decision'],'proposed','Session call, S644 (SkyWren, the conductor); docs/reference/lanes/program-requirements-harvest.md; PR 3197',null,null,'SkyWren (S644)',date '2026-11-12'),
('p-new-workflow-dispatch-needs-main-s644','pitfall','A new workflow file cannot be dispatched until it is on main','S644: the wave runner (program-requirements-wave.yml) could not be dispatched from its branch; GitHub dispatches only workflows that exist on the default branch. Merge the workflow first, then run its trial on a branch.',array['conductor','github-actions','pitfall'],'proposed','S644, PR 3191',null,null,'SkyWren (S644)',date '2026-11-12'),
('p-read-cobix-every-wake-s644','pitfall','Read COBIx''s threads at every wake, paging from the last comment','S644: the conductor missed COBIx''s 00:21Z reply for forty minutes, and his finding on #3191''s own thread was caught only because it was read before the merge. Ten full comments on #3111 cost about 10,000 tokens: page with perPage 1 from the last page.',array['conductor','cobix','pitfall'],'proposed','S644; docs/reference/conductor_mode.md',null,null,'SkyWren (S644)',date '2026-11-12'),
('p-gate-free-text-reading-per-college-s644','pitfall','Gate a free-text catalog reading per college with positive evidence first','S644 (#3193): a regex reading of free catalog text took three review rounds and still passed constructed pages; gating it to named colleges with positive evidence in the record''s own section ended it. Gate first.',array['program-requirements','pitfall'],'proposed','S644, PR 3193',null,null,'SkyWren (S644)',date '2026-11-12'),
('p-pinned-test-change-is-reversal-s644','pitfall','A decision that changes a pinned test reverses an earlier decision','S644: the conductor''s own design rules were wrong twice (the wave price rate; widening passes_live), and review and the existing tests caught both. Before changing a test''s pinned rule, read why the test exists: it records someone''s earlier decision.',array['conductor','tests','pitfall'],'proposed','S644; docs/reference/conductor_mode.md',null,null,'SkyWren (S644)',date '2026-11-12'),
('p-first-read-pr-needs-display-build-s644','pitfall','A first-read college PR cannot go green without the display build','S644 (#3194): Santiago Canyon''s first-read PR stays red on roep_display_test until the committed display build covers every filed program, which needs the dated reads refreshed for the college. Plan the dated reads and the build as part of the read (#3197).',array['program-requirements','tests','pitfall'],'proposed','S644, PR 3194',null,null,'SkyWren (S644)',date '2026-11-12')
